//! Reproducers the fuzz harness found, kept as regression tests: each is a base state an honest
//! history reached and the ops (hex) that made a replica holding it panic or hang. Each must now
//! run to the end without either: the hostile op is refused, or waits and is dropped.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{Offsets, Schema, run_case, unhex};

/// Run one case on its own thread; a hang fails the test after 20 s instead of blocking it.
fn clean(schema: Schema, base: &str, ops: &[&str]) {
    let base = unhex(base);
    let ops: Vec<Vec<u8>> = ops.iter().map(|o| unhex(o)).collect();
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let _ = tx.send(run_case(schema, &base, &ops));
    });
    match rx.recv_timeout(std::time::Duration::from_secs(20)) {
        Ok(found) => assert_eq!(found, None),
        Err(_) => panic!("the case hangs"),
    }
}

/// A string item placed beside an array's items (by its right origin) makes yrs's array iterator spin for ever once the string has a character wider than one byte (byte offsets).
#[test]
fn string_in_array_hangs_on_read() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "03020300070101610008000300027b4325cadfec04d4a27e0502000601017401620474727565840200076e61c3af7665208602060162046e756c6c0701016101280002080179017601016b7701760401002801016d026b340178060101740162047472756584010105f09f9880788601040162046e756c6c00",
        &["0104030387010000080003030175027c3fc000007f44030105f09f9880780400030508696e2061727261790301010001ffffffffffffff0f01030303010501"],
    );
}

/// An op claims clocks of client 3 ahead of it with an array type; a later op names that clock as a text and puts a string in it. The string lands in the array and a later edit spins (UTF-16 offsets).
#[test]
fn same_clock_other_content_in_utf16() {
    clean(
        Schema::Generic(Offsets::Utf16),
        "",
        &[
            "0103031cc8020102020177017847031000080003190275027c3fc000007f7e0103010009",
            "000103010009",
            "0102031d870202020400031d08696e2061727261790103010009",
            "0000",
        ],
    );
}

/// An op past a gap in client 1's clocks (yrs integrates it behind a skip), then one that fills the gap with other content under the same clock: the string inherits a map key and the map event unwraps None (yrs/types/mod.rs:806).
#[test]
fn skip_then_overlap_panics_in_map_event() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "010302000601017401620474727565840200076e61c3af7665208602060162046e756c6c00",
        &["010101022801016d026b34017800", "01030101060101740162047472756584010105f09f9880788601040162046e756c6c00"],
    );
}

/// An item whose origin sits in text 't' and whose right origin sits in another type links the two lists; a later local cut panics (yrs/types/text.rs:845).
#[test]
fn origin_and_right_in_two_parents_panics_on_edit() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "02020200050101740d7b22737263223a22696d67227d2801016d026b310175027c3fc000007f03010008010161017601016b7701762701016d026b3401280001010178017900",
        &["01010301c1020001020500"],
    );
}

/// Any content placed in a WordCraft block text: `get_string` skips it but a cut counts it, and a later local edit panics (yrs/types/text.rs:845).
#[test]
fn any_in_a_block_text_panics_on_a_live_edit() {
    clean(
        Schema::Live,
        "",
        &["01030303c6000500060162046e756c6cc303030006020102c40304000606c3a974c3a92000"],
    );
}

/// Any content placed in a text (UTF-16 offsets): a later local cut over it panics (yrs/types/text.rs:845).
#[test]
fn any_in_a_text_panics_on_edit() {
    clean(
        Schema::Generic(Offsets::Utf16),
        "03010300050101740d7b22737263223a22696d67227d0402000701017401280002000178017d012701016d026b33020400020206696e206d61700101002801016d026b32017601016b77017600",
        &["0101020424000202013106696e206d617000"],
    );
}

/// An item the doc partly holds names one parent, but once yrs trims the held part its new origin sits in another; reading the array then panics (yrs/types/array.rs:101).
#[test]
fn a_sliced_item_in_two_parents_breaks_array_read() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "0201030008010161017704f09f9880030200070101610008000200027b432dbe4a1afe62807601016b770176880200017900",
        &["0101020308000200027b432dbe4a1afe62807601016b77017600"],
    );
}

/// Found by the long run (seed 11) as a case that ran over 30 s (byte offsets). It finishes at
/// once since the fits check memoises each item's parent, including unfinished and split ones.
#[test]
fn items_beside_each_other_do_not_hang_the_check() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "020202002701016d026b31020400020006696e206d6170030100060101740162047472756584010001618601010162046e756c6c00",
        &[
            "010302050401016106696e206d6170080002070277007b432a07ada192dff8880206017800",
            "0000",
            "010203000701016101280003000179017800",
            "010203028703000008000302027704f09f98807800",
        ],
    );
}

/// A format item whose origin was collected (GC) and whose right origin sits in an array: yrs
/// finds no item at the origin and takes the right origin's parent, so the format lands in the
/// array and reading it spins (byte offsets).
#[test]
fn collected_origin_puts_a_format_in_an_array() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "",
        &[
            "01030112c60104011001620474727565c40112010505f09f988078c6011501050162046e756c6c030101000702010001030205030903",
            "01030112c60104010501620474727565c40112010505f09f988078c6011501050162046e756c6c020101040102010001",
        ],
    );
}

// Found by the second long run (seed 13). The Live cases are block-text cuts that ran past the
