/// Found by the third long run (seed 14): an item whose origin is a later clock of its own client
/// waits in yrs for ever; another update then fills those clocks with other content, the held
/// items integrate against it, and a later edit spins. Refused as a cycle.
#[test]
fn an_item_naming_a_later_clock_of_its_client_is_refused() {
    clean(
        Schema::Generic(Offsets::Bytes),
        "03010300050101740d7b22737263223a22696d67227d0202000801016101780401017405f09f988078020100070101610008000100027704f09f98807e00",
        &[
            "010401030401017403e4b8ad81010701070101610008000100027704f09f98807e00",
            "0102010487010200080001040275027c3fc000007f7900",
            "01010301c80100020001770000",
        ],
    );
}
